#!/usr/bin/env bash
# Puts the repository back to its rehearsal starting point after a rehearsal.
#
#   scripts/reset-demo.sh [--yes] [tag]        tag defaults to demo-ready
#
# Without --yes it only prints what it would do. With --yes it:
#   1. closes every open pull request and issue, except those labelled keep;
#   2. deletes the factory/*, lore/* and old reset/* branches on GitHub;
#   3. restores every factory's folder (the paths tools.json gives each tool)
#      to the tag, in one pull request labelled demo-reset. Shared files are
#      left as they are on main, so fixes made between rehearsals survive. A
#      tool with "reset": false in tools.json is left alone too: its folder is
#      not restored, and files the tag lacks there are not removed.
#
# After you merge that pull request, resend the shared context to Lore:
#   gh workflow run lore-ingest.yml
#
# What it cannot reset: Lore keeps its own record of plans, runs and transcripts
# for this repository. Those stay in Lore.
set -euo pipefail

apply=false
if [ "${1:-}" = "--yes" ]; then apply=true; shift; fi
tag="${1:-demo-ready}"

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root"
repo="$(gh repo view --json nameWithOwner --jq .nameWithOwner)"

git fetch -q origin --tags --prune
git rev-parse -q --verify "refs/tags/$tag" >/dev/null || { echo "No tag $tag. Create it first: git tag $tag && git push origin $tag" >&2; exit 1; }

paths=()
while IFS= read -r p; do paths+=("$p"); done < <(python3 scripts/repo_tools.py reset-paths)

changed="$(git diff --name-only "$tag" origin/main -- "${paths[@]}")"
prs="$(gh pr list --repo "$repo" --state open --limit 200 --json number,title,labels --jq '.[] | select([.labels[].name] | index("keep") | not) | "#\(.number) \(.title)"')"
issues="$(gh issue list --repo "$repo" --state open --limit 500 --json number,title,labels --jq '.[] | select([.labels[].name] | index("keep") | not) | "#\(.number) \(.title)"')"
branches="$(git branch -r --format='%(refname:lstrip=3)' | grep -E '^(factory|lore|reset)/' || true)"

section() { printf '\n%s\n' "$1"; if [ -n "$2" ]; then printf '%s\n' "$2" | sed 's/^/  /'; else echo "  (none)"; fi; }
echo "Reset of $repo to $tag. Factory paths: ${paths[*]}"
section "Pull requests to close:" "$prs"
section "Issues to close:" "$issues"
section "Branches to delete on GitHub:" "$branches"
section "Files in factory folders that differ from $tag:" "$changed"

if ! $apply; then
  printf '\nDry run. Run again with --yes to do it.\n'
  exit 0
fi

note="Closed by the rehearsal reset (scripts/reset-demo.sh)."
for n in $(printf '%s\n' "$prs" | grep -oE '^#[0-9]+' | tr -d '#'); do
  gh pr close "$n" --repo "$repo" --comment "$note" >/dev/null && echo "closed PR #$n"
done
for n in $(printf '%s\n' "$issues" | grep -oE '^#[0-9]+' | tr -d '#'); do
  gh issue close "$n" --repo "$repo" --reason "not planned" --comment "$note" >/dev/null && echo "closed issue #$n"
done
for b in $branches; do
  git push -q origin --delete "$b" && echo "deleted branch $b"
done

if [ -z "$changed" ]; then
  echo "Factory folders already match $tag. Nothing to restore."
  exit 0
fi

stamp="$(date -u +%Y%m%d-%H%M)"
branch="reset/$stamp"
work="$(mktemp -d)"
trap 'git worktree remove --force "$work" >/dev/null 2>&1 || true' EXIT
git worktree add -q -b "$branch" "$work" origin/main
(
  cd "$work"
  # Files the tag has: take its version. Files the tag lacks: remove them.
  git ls-tree -r --name-only "$tag" -- "${paths[@]}" | while read -r f; do git checkout -q "$tag" -- "$f"; done
  comm -13 <(git ls-tree -r --name-only "$tag" -- "${paths[@]}" | sort) <(git ls-files -- "${paths[@]}" | sort) \
    | while read -r f; do git rm -q -- "$f"; done
  # Both steps above stage their changes; no git add, which would fail on an
  # empty factory path such as specs/ before Lore has written a spec.
  git commit -q -m "Rehearsal reset: factory folders back to $tag"
  git push -q -u origin "$branch"
)

body="$(mktemp)"
cat > "$body" <<EOF
## Why

Rehearsal reset. Puts every factory's folder back to \`$tag\`, so the next run starts from the same point as the demo.

## What Changed

Factory-owned paths (${paths[*]}) restored to \`$tag\`. Shared files are untouched. Files:

$(printf '%s\n' "$changed" | sed 's/^/- /')

## Testing

The ownership check confirms this PR touches factory folders only. After merging, resend the shared context: \`gh workflow run lore-ingest.yml\`.
EOF
gh pr create --repo "$repo" --base main --head "$branch" --label demo-reset \
  --title "Rehearsal reset to $tag ($stamp)" --body-file "$body"
rm -f "$body"
echo "Merge that pull request, then run: gh workflow run lore-ingest.yml --repo $repo"


